200:     /// Non-blocking drain of background worker events (up to 256 events per frame).
201:     pub fn drain_events(&mut self) {
202:         while let Ok(resp) = self.resp_receiver.try_recv() {
203:             match resp {
204:                 UiWorkerResponse::CatalogResults(hits) => {
205:                     self.catalog_hits = hits;
