211:                     self.is_scanning_mods = false;
212:                 }
213:             }
214:         }
215: 
216:         for event in self.event_bus.try_drain(256) {
217:             match event {
218:                 Event::PhaseStarted { phase, .. } => {
219:                     self.active_phase = Some(phase);
220:                 }
221:                 Event::Progress(prog) => {
222:                     self.active_phase = Some(prog.phase.clone());
223:                     self.phase_progress = Some(prog);
224:                 }
225:                 Event::PhaseCompleted { phase, elapsed_ms } => {
226:                     self.active_phase = None;
227:                     self.phase_progress = None;
228:                     self.status_message = Some((
229:                         format!("Фаза '{phase}' успешно завершена за {elapsed_ms} мс"),
